  for (const d of [-1, 1]) { c.beginPath(); c.moveTo(x + d * w * 0.2, gy); c.quadraticCurveTo(x + d * (w * 0.2 + 16), gy - 2, x + d * (w * 0.2 + 18), gy - 18); c.stroke(); }
  c.fillStyle = `rgba(238,224,244,${haze})`;
