    const [k, raw, a = 1] = item;
    const pts = mirror ? raw.map(([x, y]) => [600 - x, y]) : raw;
    const cmds = smoothCmds(pts);
    // ทึบเต็ม: ปื้นที่คร่อมรอยต่อชิ้น (ตัว/แขน/ขา) ซ้อนกันแล้วกลืนเป็นสีเดียว — โปร่งแสงแล้วเห็นเส้นรอยต่อ/ตรงซ้อนเข้มกว่า
