    const h = (j) => hash(seed * 11.7 + i * 3.1 + j * 1.3);
    return [u0 + ((i + 0.2 + h(1) * 0.6) / n) * (u1 - u0), (h(2) - 0.5) * 1.3, kinds[i % kinds.length], 0.9, 1.1 + h(3) * 0.8, 0.34 + h(4) * 0.24, seed + i];
