/** สี #rrggbb → rgba ความเข้ม a */
const hexA = (h, a) => `rgba(${[1, 3, 5].map((i) => parseInt(h.slice(i, i + 2), 16)).join(',')},${a})`;
/**
 * ปื้นนุ่มตามท่อ (สีเปรอะ — แขนท่อ/หาง · ผู้ใช้ 21 ต.ค. "สีตรงแขนเพี้ยนหมด"): ปล้องขอบคมสลับส้ม-ดำบนแขนท่อดูเป็นลายเสือ
 * → วงรีไล่สีจางที่ขอบ (ไม่มีขอบคม) วางเหลื่อมกันตามความยาวท่อ ยาวไปตามท่อ — สีกลืนกับขนรอบ ๆ แบบปื้นบนตัว
 * blobs = [[u 0..1 ตามท่อ (โคน → ปลาย), off −1..1 ขวางท่อ, r เท่าของครึ่งความกว้างท่อ, สี, ความเข้ม?]] — ตัดในเนื้อท่อโดยชั้นของท่อเอง
 */
function calicoBlobs(ctx, G, blobs, cal) {
  const { pts, half, N } = G;
  for (const [uf, off, r, k, a = 1] of blobs) {
    const u = uf * N, i = Math.max(0, Math.min(N - 1, Math.floor(u))), f = Math.max(0, Math.min(1, u - i));
    const p = pts[i], q = pts[Math.min(N, i + 1)];
    const ang = p.a + (q.a - p.a) * f;
    const hw = half(i) + (half(Math.min(N, i + 1)) - half(i)) * f;
    const nx = -Math.sin(ang), ny = Math.cos(ang);
    const R = r * hw;
    ctx.save();
    ctx.translate(p.x + (q.x - p.x) * f + nx * off * hw, p.y + (q.y - p.y) * f + ny * off * hw);
    ctx.rotate(ang);
    ctx.scale(1.6, 1);   // ยาวไปตามท่อ
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, R);
    g.addColorStop(0, hexA(cal[k], a));
    g.addColorStop(0.5, hexA(cal[k], a * 0.85));
    g.addColorStop(1, hexA(cal[k], 0));
    ctx.fillStyle = g;
    ctx.beginPath(); ctx.arc(0, 0, R, 0, TAU); ctx.fill();
    ctx.restore();
  }
}
/** แต้มสีปลายท่อ (แขน/ขา วิเชียรมาศ): วงไล่สีที่ปลายท่อ รัศมีตามความยาวท่อ — เข้มที่อุ้งเท้า จางลงไปทางไหล่ */
function pointsTip(ctx, G, cal) {
  const { pts, N } = G, q = pts[N], q0 = pts[0];
  const len = Math.hypot(q.x - q0.x, q.y - q0.y);
  // ไม่เกินครึ่งท่อนแขน — เงาไม่ลามถึงข้อศอก (แขนท่อนบนไม่มีเงานี้ ศอกจะเห็นรอยต่อสีเข้ม/อ่อน)
  const r = cal.armTipR ? Math.min(cal.armTipR, len * 0.6) : Math.max(30, len * cal.armTip);
  const g = ctx.createRadialGradient(q.x, q.y, 0, q.x, q.y, r);
  for (const [o, c] of cal.tipStops) g.addColorStop(o, c);
  ctx.fillStyle = g;
  ctx.fillRect(q.x - r, q.y - r, r * 2, r * 2);
}

// ══ ตากลมเขียว (แบบแมวสามสี) — วาดใหม่ตามแบบ ไม่ใช้ตาแบ๊วเดิม ══
// ขอบตาครีมบาง ๆ รอบม่านตา · ม่านตาเขียวไล่จากเข้มด้านบนเป็นเขียวอมเหลืองด้านล่าง ขอบม่านตาเข้ม
// รูม่านตาน้ำตาลดำโตเกือบเต็ม (ตาโตขี้อ้อน) · ประกายขาว: วงใหญ่บนซ้าย · จุดเล็กขวา · จุดจิ๋วล่างขวา
const ROUND_EYE = {
  white: '#FFFCF4', iris: ['#2F5A22', '#5F9234', '#B4D163'], irisRim: '#24401A', glow: 'rgba(214,236,140,.5)',
  pupilIn: '#2B1B12', pupilOut: '#0E0805',
  // สำหรับตาตอนหันข้าง (sideEye ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#D4E88E', rimBot: '#6E9E3A', coreIn: '#2B1B12', coreOut: '#0E0805',
};
function drawRoundEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lidded = false, col = ROUND_EYE, starDots = false, starOne = false } = {}) {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, d = side === 'left' ? 1 : -1;
  c.save();
  c.clip(white);
  c.fillStyle = col.white;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, (R + 6) * 2);
  // ม่านตา: เกือบเต็มดวง เหลือขอบครีมบาง ๆ · เลื่อนตามสายตา
  const ix = W.x + d * 1.5 + lx * 0.9, iy = W.y - 1 + ly * 0.9, ir = R - 3.5;   // ขอบครีมรอบม่านตาบาง ๆ ตามแบบ
  const g = c.createLinearGradient(0, iy - ir, 0, iy + ir);
  g.addColorStop(0, col.iris[0]);
  g.addColorStop(0.5, col.iris[1]);
  g.addColorStop(1, col.iris[2]);
  c.fillStyle = g;
  c.beginPath(); c.arc(ix, iy, ir, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มในม่านตาครึ่งล่าง (ตาใสฉ่ำ)
  const gl = c.createRadialGradient(ix, iy + ir * 0.55, 0, ix, iy + ir * 0.55, ir * 0.75);
  gl.addColorStop(0, col.glow);
  gl.addColorStop(1, 'rgba(222,240,150,0)');
  c.fillStyle = gl;
  c.beginPath(); c.arc(ix, iy, ir, 0, TAU); c.fill();
  // รูม่านตาโต (เยื้องขึ้นนิด)
  const px = ix, py = iy - 3, pr = ir * 0.78;   // รูม่านตาโตขึ้น (ผู้ใช้ขอสองรอบ 15 ต.ค. — 0.6 → 0.7 → 0.78)   // รูม่านตาโตแต่ยังเห็นวงเขียวรอบ ๆ ชัด (ตามแบบ)
  const pg = c.createRadialGradient(px - pr * 0.25, py - pr * 0.3, pr * 0.1, px, py, pr);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.arc(px, py, pr, 0, TAU); c.fill();
  // ประกาย (ทิศแสงบนซ้ายทั้งสองตา) · ใส่ชุดที่มี starEyes: จุดเล็กเป็นดาวเหลือง (วงใหญ่คงเดิม)
  const dot = eyeDots(c, ix, iy, ir, starDots, t, starOne);
  if (lidded) {
    dot(-0.3, 0.12, 0.2, true);
    if (!starOne) dot(0.3, 0.2, 0.08);
  } else {
    dot(-0.3, -0.32, 0.28, true);
    if (!starOne) dot(0.26, 0.42, 0.1);   // จุดขาว: ตัวผู้ = วงใหญ่บนวงเดียว · ตัวเมีย = วงใหญ่บน + จุดล่างหนึ่งจุด (กฎผู้ใช้ 21 ต.ค.)
  }
  if (sparkle > 0 && !starDots) {
    // ประกายวิ้ง: ดาวเหลืองอ่อนมีแสงเรือง (ผู้ใช้ขอให้เปลี่ยนจากดาวขาว)
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    eyeStar(c, ix + 16, iy - 14, 14 * k);
    eyeStar(c, ix - 8, iy + 18, 7.5 * k);
  }
  c.restore();
}

/** สีดาวประกายในตา (ช่อง starEyes ของชุด) — yellow = ชุดขนมหวาน + ท่าตาเป็นประกาย · ice = องค์หญิงหิมะ */
const EYE_STARS = {
  yellow: { star: '#FFF29A', glow: 'rgba(255,248,170,.85)', fade: 'rgba(255,240,140,0)' },
  ice: { star: '#C4EAFF', glow: 'rgba(200,236,255,.85)', fade: 'rgba(170,222,255,0)' },
};
/** ดาวประกายในตา: ดาวสี่แฉก + แสงเรืองรอบ + แกนกลางขาว (แบบที่ผู้ใช้เลือก 15 ต.ค.) */
function eyeStar(c, x, y, r, col = EYE_STARS.yellow) {
  if (r <= 0.3) return;
  const g = c.createRadialGradient(x, y, 0, x, y, r * 1.9);
  g.addColorStop(0, col.glow);
  g.addColorStop(1, col.fade);
  c.fillStyle = g;
  c.beginPath(); c.arc(x, y, r * 1.9, 0, TAU); c.fill();
  c.fillStyle = col.star;
  c.beginPath();
  c.moveTo(x, y - r);
  c.quadraticCurveTo(x, y, x + r * 0.8, y);
  c.quadraticCurveTo(x, y, x, y + r);
  c.quadraticCurveTo(x, y, x - r * 0.8, y);
  c.quadraticCurveTo(x, y, x, y - r);
  c.fill();
  c.fillStyle = '#FFFFFF';
  c.beginPath(); c.arc(x, y, r * 0.18, 0, TAU); c.fill();
}
/**
 * ตัววาดจุดประกายในตา dot(dx, dy, r, big) — พิกัด/ขนาดเป็นสัดส่วนของวงตาดำ (ir)
 * stars = ชุดที่มี starEyes: จุดเล็ก (ไม่ใช่ big) วาดเป็น eyeStar ตรงตำแหน่งเดิม กะพริบเบา ๆ สลับจังหวะกัน
 *   ขนาดตามแบบที่ผู้ใช้เลือก: ดวงแรกใหญ่ ดวงที่สองเล็ก (ไม่ตามขนาดจุดเดิม — ตาแบ๊วจุดโต ดาวจะใหญ่จนแสงกลบตาดำ)
 *   one = แมวตัวผู้: ดาวดวงเดียว (ดวงแรก) จุดที่เหลือเป็นจุดขาวตามเดิม (ผู้ใช้สั่ง 15 ต.ค.)
 */
function eyeDots(c, ix, iy, ir, stars, t, one = false) {
  let n = 0;
  return (dx, dy, r, big = false) => {
    const x = ix + dx * ir, y = iy + dy * ir;
    if (stars && !big && !(one && n > 0)) {
      const k = 0.85 + 0.15 * Math.sin(t * 0.25 + n * 2.1);
      eyeStar(c, x, y, ir * (n++ ? 0.22 : 0.38) * k, EYE_STARS[stars] || EYE_STARS.yellow);
      return;
    }
    c.fillStyle = '#FFFFFF';
    c.beginPath(); c.arc(x, y, r * ir, 0, TAU); c.fill();
  };
}

/**
 * ขนตาของตากลม (แมวสามสี · ผู้ใช้ขอ "วาดขนตาใหม่ให้แตกต่างจากเดิม"): เส้นเปลือกตาบนเรียวบาง หนาขึ้นทางหางตา
 * + ขนตางอนแยกเป็นเส้น ๆ สามเส้นที่มุมบนนอก (โค้งงอนออกนอกหน้า ปลายแหลม) — ไม่มีแถบโอบใต้ตาแบบเดิม
 * sq/cy = ตาหรี่ (ฐานเกาะขอบตาที่หรี่ ขนตาไม่แบน) เหมือน drawLashes
 */
function drawRoundLashes(c, side, sq = 1, cy = null) {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;
  const yc = cy ?? W.y;
  const P = (a, r) => [W.x + o * Math.cos(a) * r, yc + (W.y + Math.sin(a) * r - yc) * sq];
  const N = (a) => { const nx = o * Math.cos(a) * sq, ny = Math.sin(a), l = Math.hypot(nx, ny) || 1; return [nx / l, ny / l]; };
  c.fillStyle = '#24140C';
  // เปลือกตาบน: จากหัวตาด้านบน (a −2.75) ถึงหางตา (a 0.18) หนา 1 → 5.5
  const a0 = -2.75, a1 = 0.18, n = 40, lid = new Path2D(), out = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n), u = i / n;
    // หนาสุดค่อนไปทางหางตา แล้วเรียวเป็นศูนย์ทั้งสองปลาย — ปลายกลืนเข้ากับเส้นขอบตา ไม่จบเป็นตอทื่อลอย ๆ (ผู้ใช้ทัก)
    const taper = Math.pow(Math.sin(Math.PI * u), 0.75);
    const th = (3 + 8 * Math.pow(u, 1.1)) * taper;
    // ฐานเริ่มในขอบตา (ทับเส้นขอบตา) ช่วงกลาง · ปลายทั้งสองค่อย ๆ ออกมาอยู่บนเส้นขอบตาพอดี
    const b = P(a, R - 1 - 3 * taper), nn = N(a);
    if (!i) lid.moveTo(...b); else lid.lineTo(...b);
    out.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  for (let i = n; i >= 0; i--) lid.lineTo(...out[i]);
  lid.closePath();
  c.fill(lid);
  // ขนตางอนสามเส้น (ผู้ใช้ 22 ต.ค. "ปรับให้ดูดีขึ้นแบบลายสลิด"): ทรงจันทร์เสี้ยวโค้งเดียวเนียน — เดิมขึ้นตรงแล้วหักข้างเป็นตะขอ ฐานลอยห่างเปลือกตา
  // ฐานกว้างฝังในเปลือกตา (ตามความหนาจริง ณ จุดนั้น) → ออกตั้งฉากขอบตา → ค่อย ๆ โค้งออกนอกหน้า ปลายแหลม · เส้นนอกสุดยาวและงอนมากสุด
  // [มุมบนขอบตา, ความยาว, ครึ่งความกว้างฐาน, แรงงอนออกนอก]
  for (const [a, len, w, curl] of [[-0.36, 19, 3.8, 1], [-0.72, 17, 3.5, 0.85], [-1.08, 14, 3.1, 0.7]]) {
    const u = (a - a0) / (a1 - a0), taper = Math.pow(Math.sin(Math.PI * u), 0.75);
    const th = (3 + 8 * Math.pow(u, 1.1)) * taper, nn = N(a), sd = [-nn[1], nn[0]];
    const bb = P(a, R - 1 - 3 * taper + th - 3);
    const k = [bb[0] + nn[0] * len * 0.6, bb[1] + nn[1] * len * 0.6];
    const tip = [bb[0] + nn[0] * len * 0.88 + o * len * 0.45 * curl, bb[1] + nn[1] * len * 0.88 - len * 0.08 * curl];
    const q = new Path2D();
    q.moveTo(bb[0] + sd[0] * w, bb[1] + sd[1] * w);
    q.quadraticCurveTo(k[0] + sd[0] * w * 0.6, k[1] + sd[1] * w * 0.6, ...tip);
    q.quadraticCurveTo(k[0] - sd[0] * w * 0.3, k[1] - sd[1] * w * 0.3, bb[0] - sd[0] * w, bb[1] - sd[1] * w);
    q.closePath();
    c.fill(q);
  }
}

/**
 * วงอก/พุงสีอ่อน (ท่านั่ง · นั่งเกา · วิ่ง): ทึบแบบเดิม หรือขอบฟุ้ง (soft = art.bellySoft — ไล่จางจากกลางออกขอบ ไม่เห็นขอบวงรี
 * เข้าชุดกับพุงฟุ้งตอนยืน · ศุภลักษณ์อกน้ำตาลอ่อนบนขนน้ำตาล ถ้าทึบจะเห็นเป็นวงแปะ)
 */
function bellyBlob(c, x, y, rx, ry, col, soft = false, rot = 0) {
  c.fillStyle = col;
  if (!soft) { c.beginPath(); c.ellipse(x, y, rx, ry, rot, 0, TAU); c.fill(); return; }
  const v = /^#[0-9a-f]{6}$/i.test(col) ? parseInt(col.slice(1), 16) : 0xffffff;
  const rgb = `${v >> 16},${(v >> 8) & 255},${v & 255}`;
  c.save();
  c.translate(x, y);
  c.rotate(rot);
  c.scale(rx, ry);
  const g = c.createRadialGradient(0, 0, 0, 0, 0, 1);
  g.addColorStop(0, `rgba(${rgb},.85)`);
  g.addColorStop(0.55, `rgba(${rgb},.6)`);
  g.addColorStop(1, `rgba(${rgb},0)`);
  c.fillStyle = g;
  c.beginPath(); c.arc(0, 0, 1, 0, TAU); c.fill();
  c.restore();
}
/** ลายขาวขอบฟุ้ง (แมววิลาศ): เส้นโปร่งซ้อนสามชั้นตามขอบ (ครึ่งนอกไล่จางเข้าขนดำ) แล้วลงสีเต็ม — ไม่มีขอบเทาแข็งเป็นเส้น */
function softMark(c, q, col) {
  const a0 = c.globalAlpha;
  c.strokeStyle = col;
  c.lineJoin = 'round';
  for (const [w, a] of [[6.5, 0.08], [4, 0.14], [2, 0.22]]) { c.globalAlpha = a0 * a; c.lineWidth = w; c.stroke(q); }
  c.globalAlpha = a0;
  c.fillStyle = col;
  c.fill(q);
}
// ══ ตาแมววิลาศ (ผู้ใช้ส่งแบบ 21 ต.ค.: "วาดดีไซน์ตาใหม่ ตามแบบ สีก็เหมือนเลย") ══
// ไม่มีตาขาว: ม่านตาเขียวเต็มดวง — ขอบล่างเขียวอมเหลืองสว่าง ไล่ขึ้นเป็นเขียวเข้มใต้เปลือกตา · วงเขียวเข้มรอบรูม่านตา
// รูม่านตาดำโต (ไม่เต็มดวง เห็นวงเขียวรอบ ๆ ชัด) · ประกายขาววงเดียวมุมบนขวา (ตามแบบ — ทั้งสองตา)
// เปลือกตาบนเป็นแถบเข้มหนาโอบครึ่งบน (เงาเปลือกตาตกลงในม่านตา) — วาดคู่กับ drawWilatLashes
const WILAT_EYE = {
  iris: ['#2C4A16', '#5E8E26', '#A9C846', '#DDE88A'], ring: '#1F3A10', pupilIn: '#1E1A12', pupilOut: '#0A0806',
  // สำหรับตาตอนหันข้าง/ตาปรือ (ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#C8DC6E', rimBot: '#5E8E26', coreIn: '#1E1A12', coreOut: '#0A0806',
};
/**
 * ทรงตาวิลาศ (ผู้ใช้ 21 ต.ค. รอบสาม: "ตาคมกว่านี้ เพิ่มขอบตาล่างเหมือนแบบ"): ทรงอัลมอนด์ — กว้างกว่าสูง
 * ขอบบน = เส้นเปลือกตาโค้งแบน (Pi → Po) · ขอบล่าง = โค้งกลมลึกแบบตัว U (Po → Pi) · มุมหัวตา/หางตาแหลม
 * หางตายื่นเลยวงตาและสูงกว่าหัวตา (ตาเชิดคม) · คืน { cx, cy, r, pi, po, pc, b1, b2, path } (พิกัดตาในไฟล์)
 * lid = เปลือกตาเลื่อนลงมาบัง (0 = ลืมเต็ม · ตาปรือท่าลอยฟ้า ~0.55 · ง่วง ~0.8) — มุมหัวตา/หางตาอยู่ที่เดิม เส้นเปลือกตาแบนลงมา
 *       ตาดำขนาดเท่าเดิม แค่โดนเปลือกตาบังด้านบน (ผู้ใช้ 21 ต.ค.: "ตาดำเล็กลง ให้ขนาดเท่าเดิม แค่ปิดเปลือกตาลงมา")
 */
function wilatEyeGeo(side, lid = 0) {
  const W = EYE_WHITE[side], o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const r = EYE_WHITE.r * 0.86, cx = W.x + o * 1.5, cy = W.y + 4;
  const pi = [cx - o * r * 1.0, cy - r * 0.14];        // หัวตา (ฝั่งจมูก)
  const po = [cx + o * r * 1.16, cy - r * 0.44];       // หางตา: ยื่นออกและสูงกว่า
  const pc = [cx + o * r * 0.05, cy - r * 1.14 + lid * r * 1.25];   // จุดดึงเส้นเปลือกตา (โค้งแบน) · เปลือกตาลง = จุดดึงต่ำลง
  const b1 = [cx + o * r * 1.12, cy + r * 1.0], b2 = [cx - o * r * 0.98, cy + r * 1.14];   // ขอบล่างโค้ง U
  const path = new Path2D();
  path.moveTo(...pi);
  path.quadraticCurveTo(...pc, ...po);
  path.bezierCurveTo(...b1, ...b2, ...pi);
  path.closePath();
  return { cx, cy, r, pi, po, pc, b1, b2, path, o };
}
function drawWilatEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lid = 0, col = WILAT_EYE, line = '#3A1A12', rimLight = false } = {}) {
  const E = wilatEyeGeo(side, lid), { cx, cy, r } = E;
  c.save();
  c.clip(E.path);
  // ม่านตาเต็มดวง: เข้มด้านบน (ใต้เปลือกตา) → เขียวสด → เขียวอมเหลืองสว่างที่ขอบล่าง
  const g = c.createLinearGradient(0, cy - r * 0.8, 0, cy + r);
  g.addColorStop(0, col.iris[0]);
  g.addColorStop(0.36, col.iris[1]);
  g.addColorStop(0.78, col.iris[2]);
  g.addColorStop(1, col.iris[3]);
  c.fillStyle = g;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // ขอบม่านตาเข้มขึ้นนิด (ตาดูลึก)
  const rg = c.createRadialGradient(cx, cy, r * 0.68, cx, cy, r + 2);
  rg.addColorStop(0, 'rgba(20,40,10,0)');
  rg.addColorStop(1, 'rgba(20,40,10,.45)');
  c.fillStyle = rg;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // รูม่านตา (เลื่อนตามสายตา) + วงเขียวเข้มบาง ๆ รอบ
  const px = cx + lx * 0.8, py = cy - 2 + ly * 0.8, pr = r * 0.6;   // ตาปรือก็ขนาดเท่าเดิม (เปลือกตาบังเอา)
  c.fillStyle = col.ring;
  c.globalAlpha = 0.55;
  c.beginPath(); c.arc(px, py, pr + 4.5, 0, TAU); c.fill();
  c.globalAlpha = 1;
  const pg = c.createRadialGradient(px - pr * 0.2, py - pr * 0.3, pr * 0.1, px, py, pr);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.arc(px, py, pr, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มครึ่งล่าง (ตาใส)
  const gl = c.createRadialGradient(cx, cy + r * 0.6, 0, cx, cy + r * 0.6, r * 0.7);
  gl.addColorStop(0, 'rgba(240,250,180,.38)');
  gl.addColorStop(1, 'rgba(240,250,180,0)');
  c.fillStyle = gl;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // เงาเปลือกตาตกลงในม่านตาใต้เส้นเปลือกตา
  const ld = lid * r * 0.62;   // เปลือกตาลง → เงาเลื่อนลงตาม
  const sh = c.createLinearGradient(0, cy - r * 0.8 + ld, 0, cy - r * 0.15 + ld);
  sh.addColorStop(0, 'rgba(8,14,4,.62)');
  sh.addColorStop(1, 'rgba(8,14,4,0)');
  c.fillStyle = sh;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, r + ld);
  // ประกายขาววงเดียวมุมบนขวาของรูม่านตา (ตามแบบ)
  c.fillStyle = '#FFFFFF';
  c.beginPath(); c.arc(px + pr * 0.4, py - pr * 0.3 + Math.min(1, lid) * pr * 0.4, r * 0.17, 0, TAU); c.fill();   // เปลือกตาลง: ประกายต่ำลงนิด ไม่จมใต้เปลือกตา
  if (sparkle > 0) {
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    star4(c, px - pr * 0.45, py + pr * 0.5, 8 * k);
  }
  c.restore();
  // ขอบตาล่าง (ตามแบบ): เส้นเข้มหนากลางตา เรียวแหลมไปหาหัวตา/หางตา — ไล่ตามโค้งล่างของตา
  const { po, pi, b1, b2 } = E;
  const B = (u) => {
    const v = 1 - u;
    return [v * v * v * po[0] + 3 * v * v * u * b1[0] + 3 * v * u * u * b2[0] + u * u * u * pi[0], v * v * v * po[1] + 3 * v * v * u * b1[1] + 3 * v * u * u * b2[1] + u * u * u * pi[1]];
  };
  const n = 30, inn = [], out = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n, [x, y] = B(u), [x0, y0] = B(Math.max(0, u - 0.01)), [x1, y1] = B(Math.min(1, u + 0.01));
    const l = Math.hypot(x1 - x0, y1 - y0) || 1;
    let nx = -(y1 - y0) / l, ny = (x1 - x0) / l;
    if (ny < 0) { nx = -nx; ny = -ny; }   // ชี้ลง (ออกนอกตา)
    // rimLight = ขนดำรอบตา: ขอบตาล่างเป็นสีขาว บางกว่าเปลือกตาบน (ผู้ใช้ 22 ต.ค.)
    const th = rimLight ? 0.4 + 2.2 * Math.pow(Math.sin(Math.PI * u), 0.7) : 1 + 4.2 * Math.pow(Math.sin(Math.PI * u), 0.7);
    inn.push([x - nx * 0.8, y - ny * 0.8]);
    out.push([x + nx * th, y + ny * th]);
  }
  const rim = new Path2D();
  rim.moveTo(...inn[0]);
  for (const q of inn.slice(1)) rim.lineTo(...q);
  for (let i = n; i >= 0; i--) rim.lineTo(...out[i]);
  rim.closePath();
  c.fillStyle = rimLight ? LASH_LIGHT : line;
  c.fill(rim);
}
/**
 * เปลือกตาบนของตาวิลาศ (ตามแบบ): แถบดำหนาตามเส้นเปลือกตาโค้งแบน หนาสุดค่อนไปทางหางตา
 * เลยหางตาออกไปเป็นปลายเชิดแหลม + ขนตางอนสองเส้นเล็กเหนือหางตา · sq/cy = ตาหรี่ (บีบรอบ cy) เหมือน drawLashes
 */
function drawWilatLashes(c, side, sq = 1, cyS = null, ink = '#0E0A08', lid = 0) {
  const E = wilatEyeGeo(side, lid), { pi, po, pc, o, cx, r } = E;
  const yc = cyS ?? EYE_WHITE[side].y;
  const S = ([x, y]) => [x, yc + (y - yc) * sq];
  const Q = (u) => {   // จุดบนเส้นเปลือกตา + ทิศตั้งฉากชี้ขึ้น
    const v = 1 - u;
    const x = v * v * pi[0] + 2 * v * u * pc[0] + u * u * po[0], y = v * v * pi[1] + 2 * v * u * pc[1] + u * u * po[1];
    const dx = 2 * v * (pc[0] - pi[0]) + 2 * u * (po[0] - pc[0]), dy = 2 * v * (pc[1] - pi[1]) + 2 * u * (po[1] - pc[1]);
    const l = Math.hypot(dx, dy) || 1;
    let nx = dy / l, ny = -dx / l;
    if (ny > 0) { nx = -nx; ny = -ny; }
    return { x, y, nx, ny };
  };
  c.fillStyle = ink;
  const n = 36, top = [], bot = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n, q = Q(u);
    const th = (2 + 8.5 * Math.pow(u, 0.9)) * Math.min(1, u * 6 + 0.25);   // หัวตาบาง → หางตาหนา
    bot.push(S([q.x - q.nx * 2, q.y - q.ny * 2]));
    top.push(S([q.x + q.nx * th, q.y + q.ny * th]));
  }
  // ปลายเชิดเลยหางตา (ผู้ใช้ 22 ต.ค. "หางให้เท่ากัน โค้งมนสวย" แล้ว "ยังไม่สวย"): หางแบบอายไลเนอร์ปีก —
  // ขอบล่างพุ่งตรงขึ้น-ออกนอกหน้าจากหางตา · ขอบบนโค้งเว้ากลับมาเกาะเปลือกตา → สามเหลี่ยมเรียวชิ้นเดียว ไม่จุ่มลงแล้วตวัดเป็นตะขอ
  const D = [o / Math.hypot(1, 0.62), -0.62 / Math.hypot(1, 0.62)];   // ทิศหาง: ขึ้น-ออกนอกหน้า ~32° (ต่อแนวขอบตาล่างที่โค้งขึ้นมาหาหางตา)
  const lo1 = [po[0] - Q(1).nx * 2, po[1] - Q(1).ny * 2];
  const tip = [po[0] + D[0] * 19, po[1] + D[1] * 19];
  const i0 = Math.round(n * 0.82);   // ขอบบนของหางกลับมาเกาะเปลือกตาก่อนถึงหางตา → หางทึบชิ้นเดียว ไม่มีรอยหัก/ตะขอ
  const band = new Path2D();
  band.moveTo(...bot[0]);
  for (const p of bot.slice(1)) band.lineTo(...p);
  band.quadraticCurveTo(...S([lo1[0] + D[0] * 9, lo1[1] + D[1] * 9 + 1.5]), ...S(tip));   // ขอบล่าง: เกือบตรง โค้งท้องนิด
  const back = top[i0];
  band.quadraticCurveTo(...S([(tip[0] + po[0]) / 2 - D[0] * 1, (tip[1] + po[1]) / 2 - 8]), ...back);   // ขอบบน: โค้งเว้ารับกับเปลือกตา
  for (let i = i0 - 1; i >= 0; i--) band.lineTo(...top[i]);
  band.closePath();
  c.fill(band);
  // ขนตางอนสองเส้นเหนือหางตา (ผู้ใช้ 22 ต.ค. ปรับแบบลายสลิด): จันทร์เสี้ยวโค้งเดียวเนียน ไม่หักเป็นตะขอ
  for (const [u, len, w, curl] of [[0.8, 15, 3, 1], [0.6, 12, 2.6, 0.8]]) {
    const q = Q(u), th = 2 + 8.5 * Math.pow(u, 0.9);
    const b = [q.x + q.nx * (th - 3), q.y + q.ny * (th - 3)];
    const k = [b[0] + q.nx * len * 0.6, b[1] + q.ny * len * 0.6];
    const tp = [b[0] + q.nx * len * 0.88 + o * len * 0.45 * curl, b[1] + q.ny * len * 0.88 - len * 0.08 * curl];
    const sd = [-q.ny, q.nx];
    const p = new Path2D();
    p.moveTo(...S([b[0] + sd[0] * w, b[1] + sd[1] * w]));
    p.quadraticCurveTo(...S([k[0] + sd[0] * w * 0.6, k[1] + sd[1] * w * 0.6]), ...S(tp));
    p.quadraticCurveTo(...S([k[0] - sd[0] * w * 0.3, k[1] - sd[1] * w * 0.3]), ...S([b[0] - sd[0] * w, b[1] - sd[1] * w]));
    p.closePath();
    c.fill(p);
  }
  void cx; void r;
}
// ══ ตาแมวศุภลักษณ์ (ผู้ใช้ส่งแบบ 21 ต.ค.: ตาเหลืองอำพัน · ตัวผู้) ══
// ทรงกลมโต ตัดด้วยเส้นเปลือกตาบนที่เอียงต่ำลงหาจมูก (หน้าเท่ ๆ ดุนิด ๆ ตามแบบ) — หางตาสูง หัวตาอยู่ระดับกลางตา
// ไม่มีตาขาว: ม่านตาอำพันเต็มดวง เข้มใต้เปลือกตา → ทอง → เหลืองสว่างขอบล่าง · รูม่านตาน้ำตาลดำโต เยื้องเข้าหาจมูกนิด (มองตรงมาที่คนดู)
// ประกายขาววงเดียวบนรูม่านตา (ตามแบบ) · เปลือกตาบนแถบเข้มหนาไปทางหางตา + ปลายตวัดสั้น ๆ (ตัวผู้ ไม่มีขนตา)
const SUPHA_EYE = {
  iris: ['#7A4A12', '#C88A1E', '#EDB838', '#F7D874'], ring: '#6E4210', pupilIn: '#6A3A16', pupilOut: '#180A04',
  // สำหรับตาตอนหันข้าง (sideEye ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#F7D874', rimBot: '#D99A22', coreIn: '#4A2A12', coreOut: '#160A04',
};
/**
 * ทรงตาศุภลักษณ์: วงกลม (r) ตัดด้านบนด้วยเส้นเปลือกตา Pi (หัวตา ระดับกลางตา) → Po (หางตา สูง บนวงตา) ผ่านจุดดึง Pc
 * lid = เปลือกตาเลื่อนลง (ตาปรือ/ง่วง — ตาดำขนาดเท่าเดิม แบบวิลาศ) · คืน { cx, cy, r, pi, po, pc, ai, ao, path, o }
 */
function suphaEyeGeo(side, lid = 0) {
  const W = EYE_WHITE[side], o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const r = EYE_WHITE.r * 0.98, cx = W.x, cy = W.y + 4;
  // มุมหัวตา (ฝั่งจมูก) / หางตา บนวงตา · เปลือกตาลง: หางตาเลื่อนลงตามวงตาด้วย (เส้นเปลือกตาแบนลง ไม่หักเป็นตัว V ดูโกรธ)
  const ai = Math.atan2(-0.04, -o), ao = Math.atan2(-0.5, o * 0.866) + o * lid * 0.45;
  const pi = [cx + r * Math.cos(ai), cy + r * Math.sin(ai)], po = [cx + r * Math.cos(ao), cy + r * Math.sin(ao)];
  const pc = [cx - o * r * 0.05, cy - r * 0.74 + lid * r];   // เส้นเปลือกตาโก่งขึ้นนิด · เปลือกตาลง = จุดดึงต่ำลง
  const path = new Path2D();
  path.moveTo(...pi);
  path.quadraticCurveTo(...pc, ...po);
  path.arc(cx, cy, r, ao, ai, o < 0);   // ขอบล่างวนตามวงตาจากหางตาผ่านใต้ตากลับหัวตา
  path.closePath();
  return { cx, cy, r, pi, po, pc, ai, ao, path, o };
}
function drawSuphaEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lid = 0, col = SUPHA_EYE, line = '#3A1C0E' } = {}) {
  const E = suphaEyeGeo(side, lid), { cx, cy, r, o } = E;
  c.save();
  c.clip(E.path);
  // ม่านตาอำพันเต็มดวง: เข้มด้านบน → ทอง → เหลืองสว่างขอบล่าง
  const g = c.createLinearGradient(0, cy - r * 0.7, 0, cy + r);
  g.addColorStop(0, col.iris[0]);
  g.addColorStop(0.34, col.iris[1]);
  g.addColorStop(0.72, col.iris[2]);
  g.addColorStop(1, col.iris[3]);
  c.fillStyle = g;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // ขอบม่านตาเข้มขึ้นนิด (ตาดูลึก กลม)
  const rg = c.createRadialGradient(cx, cy, r * 0.66, cx, cy, r + 2);
  rg.addColorStop(0, 'rgba(90,50,8,0)');
  rg.addColorStop(1, 'rgba(90,50,8,.5)');
  c.fillStyle = rg;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // รูม่านตาโต เยื้องเข้าหาจมูกนิด (ตามแบบ) + วงอำพันเข้มบาง ๆ รอบ
  const px = cx - o * r * 0.14 + lx * 0.8, py = cy + 1 + ly * 0.8, pr = r * 0.52;
  c.fillStyle = col.ring;
  c.globalAlpha = 0.5;
  c.beginPath(); c.arc(px, py, pr + 4, 0, TAU); c.fill();
  c.globalAlpha = 1;
  const pg = c.createRadialGradient(px, py + pr * 0.45, pr * 0.1, px, py, pr);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.arc(px, py, pr, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มครึ่งล่าง (ตาใสเป็นแก้วอำพัน)
  const gl = c.createRadialGradient(cx, cy + r * 0.62, 0, cx, cy + r * 0.62, r * 0.7);
  gl.addColorStop(0, 'rgba(255,196,80,.32)');
  gl.addColorStop(1, 'rgba(255,196,80,0)');
  c.fillStyle = gl;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, (r + 6) * 2);
  // เงาเปลือกตาตกลงในม่านตาใต้เส้นเปลือกตา (เลื่อนตามเปลือกตาที่ลง)
  const ld = lid * r * 0.65;
  const sh = c.createLinearGradient(0, cy - r * 0.62 + ld, 0, cy - r * 0.05 + ld);
  sh.addColorStop(0, 'rgba(40,18,2,.6)');
  sh.addColorStop(1, 'rgba(40,18,2,0)');
  c.fillStyle = sh;
  c.fillRect(cx - r - 6, cy - r - 6, (r + 6) * 2, r + 6 + ld);
  // ประกายขาววงเดียวบนรูม่านตา (ตามแบบ) — เปลือกตาลงต่ำ ประกายลงตามนิด ไม่จมใต้เปลือกตา
  c.fillStyle = '#FFFFFF';
  c.beginPath(); c.arc(px + pr * 0.12, py - pr * 0.58 + Math.min(1, lid) * pr * 0.5, r * 0.15, 0, TAU); c.fill();
  if (sparkle > 0) {
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    star4(c, px - pr * 0.5, py + pr * 0.45, 8 * k);
  }
  c.restore();
  // ขอบตา: เส้นบางรอบวงตาด้านล่าง (เปลือกตาบนวาดใน drawSuphaLashes)
  c.strokeStyle = line;
  c.lineWidth = EYE_RIM_W;
  c.lineJoin = 'round';
  c.stroke(E.path);
}
/**
 * เปลือกตาบนตาศุภลักษณ์ (ตามแบบ): แถบน้ำตาลดำหนาตามเส้นเปลือกตาเอียง บางที่หัวตา หนาไปทางหางตา
 * เลยหางตาออกไปเป็นปลายตวัดสั้น ๆ (ตัวผู้ ไม่มีขนตา) · sq/cy = ตาหรี่ (บีบรอบ cy) · lid = เปลือกตาเลื่อนลง
 */
function drawSuphaLashes(c, side, sq = 1, cyS = null, ink = '#22100A', lid = 0) {
  const { pi, po, pc, o } = suphaEyeGeo(side, lid);
  const yc = cyS ?? EYE_WHITE[side].y;
  const S = ([x, y]) => [x, yc + (y - yc) * sq];
  const Q = (u) => {   // จุดบนเส้นเปลือกตา + ทิศตั้งฉากชี้ขึ้น
    const v = 1 - u;
    const x = v * v * pi[0] + 2 * v * u * pc[0] + u * u * po[0], y = v * v * pi[1] + 2 * v * u * pc[1] + u * u * po[1];
    const dx = 2 * v * (pc[0] - pi[0]) + 2 * u * (po[0] - pc[0]), dy = 2 * v * (pc[1] - pi[1]) + 2 * u * (po[1] - pc[1]);
    const l = Math.hypot(dx, dy) || 1;
    let nx = dy / l, ny = -dx / l;
    if (ny > 0) { nx = -nx; ny = -ny; }
    return { x, y, nx, ny, tx: dx / l, ty: dy / l };
  };
  const n = 32, top = [], bot = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n, q = Q(u);
    const th = (2 + 7 * Math.pow(u, 0.9)) * Math.min(1, u * 6 + 0.25);   // หัวตาบาง → หางตาหนา
    bot.push(S([q.x - q.nx * 2, q.y - q.ny * 2]));
    top.push(S([q.x + q.nx * th, q.y + q.ny * th]));
  }
  // ปลายตวัดสั้น ๆ เลยหางตา (ต่อทิศเส้นเปลือกตาออกไปแล้วเชิดขึ้นนิด)
  const e = Q(1);
  const tip = S([po[0] + e.tx * 11 + o * 2, po[1] + e.ty * 11 - 5]);
  const band = new Path2D();
  band.moveTo(...bot[0]);
  for (const p of bot.slice(1)) band.lineTo(...p);
  band.quadraticCurveTo(...S([po[0] + e.tx * 6, po[1] + e.ty * 6 + 1]), ...tip);
  band.quadraticCurveTo(...S([po[0] + e.tx * 4, po[1] + e.ty * 4 - 7]), ...top[n]);
  for (let i = n - 1; i >= 0; i--) band.lineTo(...top[i]);
  band.closePath();
  c.fillStyle = ink;
  c.fill(band);
}
// ══ ตาแมวโคราช (ผู้ใช้ส่งแบบ 21 ต.ค.: ตาเขียวสดใส/เขียวมรกต · ตัวผู้) ══
// ตากลมโต ม่านตาเต็มดวง: ขอบนอกเขียวมินต์อ่อน → เขียวมรกต → วงเขียวเข้มรอบรูม่านตา · รูม่านตาดำอมเขียวโตปานกลาง (เห็นวงเขียวชัด)
// ประกายขาว: วงใหญ่บนซ้าย + จุดเล็กล่างขวา (ตามแบบ) · เปลือกตาบนเส้นเข้มบาง หนาขึ้นกลางตาค่อนหางตา (ตัวผู้ ไม่มีขนตา)
const KORAT_EYE = {
  iris: ['#2C8048', '#46A866', '#8CD39C', '#BDEBC4'], ring: '#1A5230', top: 'rgba(10,40,22,.55)', glow: 'rgba(206,255,214,.4)',
  pupilIn: '#21402C', pupilOut: '#06140C',
  // สำหรับตาตอนหันข้าง (sideEye ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#BDEBC4', rimBot: '#3F9E5E', coreIn: '#21402C', coreOut: '#06140C',
};
function drawKoratEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lidded = false, col = KORAT_EYE, starDots = false, starOne = false } = {}) {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, d = side === 'left' ? 1 : -1;   // d = ทิศไปหาจมูก
  c.save();
  c.clip(white);
  // ม่านตาเต็มดวง: กลางเขียวมรกตเข้ม → ขอบนอกเขียวมินต์สว่าง
  const g = c.createRadialGradient(W.x, W.y, 0, W.x, W.y, R + 2);
  g.addColorStop(0, col.iris[0]);
  g.addColorStop(0.58, col.iris[1]);
  g.addColorStop(0.86, col.iris[2]);
  g.addColorStop(1, col.iris[3]);
  c.fillStyle = g;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, (R + 6) * 2);
  // เงาเปลือกตาด้านบน (ตาดูลึก ครึ่งล่างสว่าง)
  const sh = c.createLinearGradient(0, W.y - R, 0, W.y);
  sh.addColorStop(0, col.top);
  sh.addColorStop(1, 'rgba(10,40,22,0)');
  c.fillStyle = sh;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, R + 6);
  // รูม่านตา (เลื่อนตามสายตา) + วงเขียวเข้มรอบ
  // วงเขียวเข้มด้านในโตขึ้น (ผู้ใช้ 21 ต.ค. "ตาข้างในสีเขียวเข้มกลมใหญ่กว่านี้") — รูม่านตา 0.5R → 0.6R · วงเข้มรอบหนาขึ้น
  const ix = W.x + d * 2 + lx * 0.9, iy = W.y - 1 + ly * 0.9, pr = R * 0.6;
  c.fillStyle = col.ring;
  c.globalAlpha = 0.75;
  c.beginPath(); c.arc(ix, iy, pr + 9, 0, TAU); c.fill();
  c.globalAlpha = 1;
  const pg = c.createRadialGradient(ix, iy + pr * 0.4, pr * 0.1, ix, iy, pr);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.arc(ix, iy, pr, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มครึ่งล่าง (ตาใสเป็นแก้ว)
  const gl = c.createRadialGradient(W.x, W.y + R * 0.6, 0, W.x, W.y + R * 0.6, R * 0.75);
  gl.addColorStop(0, col.glow);
  gl.addColorStop(1, 'rgba(206,255,214,0)');
  c.fillStyle = gl;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, (R + 6) * 2);
  // ประกาย (ทิศแสงบนซ้ายทั้งสองตา): วงใหญ่บนซ้าย + จุดเล็กล่างขวา · ตาปรือย้ายลงครึ่งล่างที่ยังเห็น
  const ir = R * 0.72;   // ตามรูม่านตาที่โตขึ้น (ประกายยังอยู่บนรูม่านตา)
  const dot = eyeDots(c, ix, iy, ir, starDots, t, starOne);
  if (lidded) { dot(-0.3, 0.08, 0.24, true); if (!starOne) dot(0.5, 0.42, 0.1); }
  else { dot(-0.26, -0.42, 0.3, true); if (!starOne) dot(0.52, 0.26, 0.12); }   // ตัวผู้: วงใหญ่วงเดียว (กฎผู้ใช้)
  if (sparkle > 0 && !starDots) {
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    star4(c, ix + 16, iy - 14, 12 * k);
    if (sparkle > 0.6) star4(c, ix - 8, iy + 18, 6 * k);
  }
  c.restore();
}
/**
 * เปลือกตาบนของตาโคราช (ตามแบบ): เส้นเข้มโค้งตามขอบตาด้านบน เรียวที่หัวตา/หางตา หนาสุดกลางค่อนหางตา — ตัวผู้ไม่มีขนตา
 * sq/cy = ตาหรี่ (ฐานเกาะขอบตาที่หรี่) เหมือน drawRoundLashes
 */
function drawKoratLashes(c, side, sq = 1, cy = null, ink = '#2A1E1C') {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const yc = cy ?? W.y;
  const P = (a, r) => [W.x + o * Math.cos(a) * r, yc + (W.y + Math.sin(a) * r - yc) * sq];
  const N = (a) => { const nx = o * Math.cos(a) * sq, ny = Math.sin(a), l = Math.hypot(nx, ny) || 1; return [nx / l, ny / l]; };
  c.fillStyle = ink;
  // หัวตาด้านบน (a −2.7) → หางตา (a −0.12)
  const a0 = -2.7, a1 = -0.12, n = 40, lid = new Path2D(), out = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n), u = i / n;
    const taper = Math.pow(Math.sin(Math.PI * u), 0.7);
    const th = (3.5 + 6.5 * Math.pow(u, 0.9)) * taper;   // หนากว่าเส้นขอบตาชัด ๆ (ตามแบบ)
    const b = P(a, R - 1 - 2 * taper), nn = N(a);
    if (!i) lid.moveTo(...b); else lid.lineTo(...b);
    out.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  for (let i = n; i >= 0; i--) lid.lineTo(...out[i]);
  lid.closePath();
  c.fill(lid);
}
// ══ ตาแมวสีเปรอะ (ตัวผู้ · ผู้ใช้ 21 ต.ค. "เปลี่ยนตาได้เลย อยากให้น้องแตกต่างกัน") — ตาเฮเซลสองชั้น ══
// ม่านตาเต็มดวง: วงในรอบรูม่านตาทองแดง → อำพัน → เขียวอมเหลือง → ขอบนอกเขียวมะกอกเข้ม (เข้ากับขนส้ม-ดำ — ตัวอื่นไม่มีตาสองชั้น)
// เส้นใยม่านตาเป็นรัศมีรอบรูม่านตา (สว่าง/เข้มสลับ) · รูม่านตารีตั้งนุ่ม ๆ (ตาแมวซน — ตัวอื่นกลมหมด) · ประกายวงใหญ่บนซ้ายวงเดียว (ตัวผู้)
const HAZEL_EYE = {
  iris: ['#B4561C', '#DE9632', '#CDB540', '#86A63C', '#476A2C'], fiber: 'rgba(255,222,150,.38)', fiberD: 'rgba(72,40,12,.3)',
  top: 'rgba(28,18,8,.5)', glow: 'rgba(255,236,170,.3)', pupilIn: '#2C1A0E', pupilOut: '#070403',
  // สำหรับตาตอนหันข้าง (sideEye ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#E2C25E', rimBot: '#7FA23A', coreIn: '#2C1A0E', coreOut: '#070403',
};
function drawHazelEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lidded = false, col = HAZEL_EYE, starDots = false, starOne = false } = {}) {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, d = side === 'left' ? 1 : -1;   // d = ทิศไปหาจมูก
  c.save();
  c.clip(white);
  const ix = W.x + d * 2 + lx * 0.9, iy = W.y - 1 + ly * 0.9;
  // ม่านตา: ศูนย์กลางตามรูม่านตา (กลอกตาแล้ววงทองแดงตามไป) ไล่ออกถึงขอบเขียวมะกอก
  const g = c.createRadialGradient(ix, iy, R * 0.16, ix, iy, R + 4);
  [0, 0.34, 0.54, 0.78, 1].forEach((o, i) => g.addColorStop(o, col.iris[i]));
  c.fillStyle = g;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, (R + 6) * 2);
  // เส้นใยม่านตา: ขีดรัศมีบาง ๆ สลับสว่าง/เข้ม จากขอบรูม่านตาออกไปกลางม่านตา
  c.lineCap = 'round';
  for (let i = 0; i < 22; i++) {
    const a = (i / 22) * TAU + 0.13, r0 = R * 0.36, r1 = R * (0.6 + 0.2 * hash(i + 931));
    c.strokeStyle = i % 2 ? col.fiber : col.fiberD;
    c.lineWidth = i % 2 ? 2.2 : 1.6;
    c.beginPath(); c.moveTo(ix + Math.cos(a) * r0, iy + Math.sin(a) * r0); c.lineTo(ix + Math.cos(a) * r1, iy + Math.sin(a) * r1); c.stroke();
  }
  // เงาเปลือกตาบน (ตาลึก ครึ่งล่างสว่าง)
  const sh = c.createLinearGradient(0, W.y - R, 0, W.y + 4);
  sh.addColorStop(0, col.top);
  sh.addColorStop(1, 'rgba(28,18,8,0)');
  c.fillStyle = sh;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, R + 10);
  // รูม่านตารีตั้งนุ่ม ๆ
  const prx = R * 0.34, pry = R * 0.5;
  const pg = c.createRadialGradient(ix - prx * 0.2, iy - pry * 0.25, 1, ix, iy, pry);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.ellipse(ix, iy, prx, pry, 0, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มครึ่งล่าง (ตาใส)
  const gl = c.createRadialGradient(W.x, W.y + R * 0.62, 0, W.x, W.y + R * 0.62, R * 0.7);
  gl.addColorStop(0, col.glow);
  gl.addColorStop(1, 'rgba(255,236,170,0)');
  c.fillStyle = gl;
  c.fillRect(W.x - R - 6, W.y - R - 6, (R + 6) * 2, (R + 6) * 2);
  // ประกาย: วงใหญ่บนซ้าย · จุดเล็กล่างขวาเฉพาะตัวเมีย (กฎผู้ใช้) — ชุดที่มี starEyes: ดาวหนึ่งดวงแบบตัวผู้ตัวอื่น
  const ir = R * 0.7;
  const dot = eyeDots(c, ix, iy, ir, starDots, t, starOne);
  if (lidded) { dot(-0.32, 0.1, 0.24, true); if (starDots || !starOne) dot(0.46, 0.44, 0.1); }
  else { dot(-0.3, -0.4, 0.3, true); if (starDots || !starOne) dot(0.5, 0.3, 0.11); }
  if (sparkle > 0 && !starDots) {
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    star4(c, ix + 16, iy - 14, 12 * k);
    if (sparkle > 0.6) star4(c, ix - 8, iy + 18, 6 * k);
  }
  c.restore();
}
/**
 * เปลือกตาของตาสีเปรอะ (ตัวผู้ ไม่มีขนตา): เส้นเปลือกตาบนหนาขึ้นไปทางหางตา ปลายมนยื่นเลยหางตานิด
 * + ขีดใต้หางตาสั้น ๆ (เส้นขอบตาล่างด้านนอก — ตาดูคมแบบหนุ่มซน · ต่างจากโคราช/ศุภลักษณ์)
 * sq/cy = ตาหรี่ (ฐานเกาะขอบตาที่หรี่) เหมือน drawRoundLashes
 */
function drawHazelLashes(c, side, sq = 1, cy = null, ink = '#1E120C') {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const yc = cy ?? W.y;
  const P = (a, r) => [W.x + o * Math.cos(a) * r, yc + (W.y + Math.sin(a) * r - yc) * sq];
  const N = (a) => { const nx = o * Math.cos(a) * sq, ny = Math.sin(a), l = Math.hypot(nx, ny) || 1; return [nx / l, ny / l]; };
  c.fillStyle = ink;
  // เปลือกตาบน: หัวตา (a −2.75) → หางตา (a 0.02) หนา 2 → 9 แล้วปลายมนยื่นออกไป
  const a0 = -2.75, a1 = 0.02, n = 40, lid = new Path2D(), out = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n), u = i / n;
    const th = (2 + 7 * Math.pow(u, 1.25)) * Math.min(1, u * 5 + 0.3);
    const b = P(a, R - 1.5), nn = N(a);
    if (!i) lid.moveTo(...b); else lid.lineTo(...b);
    out.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  const e = P(a1, R - 1.5), et = out[n];
  lid.quadraticCurveTo(W.x + o * (R + 9), yc + (W.y + 3 - yc) * sq, (e[0] + et[0]) / 2 + o * 7, (e[1] + et[1]) / 2);
  lid.quadraticCurveTo(W.x + o * (R + 9), yc + (W.y - 9 - yc) * sq, ...et);
  for (let i = n - 1; i >= 0; i--) lid.lineTo(...out[i]);
  lid.closePath();
  c.fill(lid);
  // ขีดใต้หางตา: เส้นโค้งตามขอบตาล่างด้านนอก (a 0.32 → 0.95) เรียวสองปลาย
  const b0 = 0.32, b1 = 0.95, m = 16, low = new Path2D(), lo = [];
  for (let i = 0; i <= m; i++) {
    const a = b0 + (b1 - b0) * (i / m), th = 3.2 * Math.sin(Math.PI * (i / m));
    const b = P(a, R + 1), nn = N(a);
    if (!i) low.moveTo(...b); else low.lineTo(...b);
    lo.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  for (let i = m; i >= 0; i--) low.lineTo(...lo[i]);
  low.closePath();
  c.fill(low);
}
// ══ ตาแมวลายวัว (ตัวเมีย) ══
// รอบสอง (ผู้ใช้ 22 ต.ค. "ปรับทรงตาให้เหมือนแบบ คล้ายตาวิลาศ ประยุกต์ได้"): ทรงอัลมอนด์กลมโต (กลมกว่าวิลาศ)
// ม่านตาเต็มดวงไม่มีตาขาว: เขียวขี้ม้าเข้มใต้เปลือกตา → เขียวมะกอก → เหลืองมะนาวสว่างขอบล่าง (ตามแบบ)
// รูม่านตาดำโต + วงเขียวเข้มฟุ้งรอบ · ประกาย (ตัวเมีย): วงใหญ่บน + จุดเล็กล่าง
// เปลือกตาบนไลเนอร์หนาไปหางตา + ปลายเชิด + ขนตางอนสามเส้นที่มุมบนนอก · ขอบตาล่างเส้นบาง (drawDollLashes)
const DOLL_EYE = {
  iris: ['#34400E', '#7E8E24', '#C4C844', '#F0EA92'], ring: '#2A3208', pupilIn: '#1C1E0A', pupilOut: '#040402',
  glow: 'rgba(250,246,176,.42)',
  // สำหรับตาตอนหันข้าง (sideEye ใช้ชุดสีแบบตาแบ๊ว)
  rimTop: '#ECE78A', rimBot: '#6E7E1C', coreIn: '#1C1E0A', coreOut: '#040402',
};
/**
 * ทรงตาลายวัว: หัวตา Pi (ระดับกลางตา) → ขอบบนโค้งกลม (เบซิเยร์ c1 c2) → หางตา Po (สูงกว่านิด ยื่นออก) → ขอบล่างโค้ง U (b1 b2)
 * lid = เปลือกตาเลื่อนลง (ตาปรือ/ง่วง) — มุมตาที่เดิม ตาดำขนาดเท่าเดิม (แบบวิลาศ) · คืน { cx, cy, r, pi, po, c1, c2, b1, b2, path, o, top(u), bot(u) }
 */
function dollEyeGeo(side, lid = 0) {
  const W = EYE_WHITE[side], o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const r = EYE_WHITE.r * 0.95, cx = W.x + o * 1, cy = W.y + 3;
  const pi = [cx - o * r * 0.98, cy + r * 0.06];
  const po = [cx + o * r * 1.1, cy - r * 0.3];
  const dl = lid * r * 1.45;
  const c1 = [cx - o * r * 0.66, cy - r * 1.28 + dl], c2 = [cx + o * r * 0.6, cy - r * 1.36 + dl];
  const b1 = [cx + o * r * 1.1, cy + r * 1.02], b2 = [cx - o * r * 0.95, cy + r * 1.12];
  const cub = (a, p, q, b) => (u) => {
    const v = 1 - u;
    return [v * v * v * a[0] + 3 * v * v * u * p[0] + 3 * v * u * u * q[0] + u * u * u * b[0], v * v * v * a[1] + 3 * v * v * u * p[1] + 3 * v * u * u * q[1] + u * u * u * b[1]];
  };
  const path = new Path2D();
  path.moveTo(...pi);
  path.bezierCurveTo(...c1, ...c2, ...po);
  path.bezierCurveTo(...b1, ...b2, ...pi);
  path.closePath();
  return { cx, cy, r, pi, po, c1, c2, b1, b2, path, o, top: cub(pi, c1, c2, po), bot: cub(po, b1, b2, pi) };
}
function drawDollEye(c, white, side, { lx = 0, ly = 0, sparkle = 0, t = 0, lid = 0, col = DOLL_EYE, starDots = false, starOne = false } = {}) {
  const E = dollEyeGeo(side, lid), { cx, cy, r } = E;
  c.save();
  c.clip(E.path);
  // ม่านตาเต็มดวง: เข้มด้านบน → เขียวมะกอก → เหลืองมะนาวขอบล่าง
  const g = c.createLinearGradient(0, cy - r * 0.9, 0, cy + r * 0.95);
  [0, 0.3, 0.64, 1].forEach((s, i) => g.addColorStop(s, col.iris[i]));
  c.fillStyle = g;
  c.fillRect(cx - r - 8, cy - r - 8, (r + 8) * 2, (r + 8) * 2);
  // ขอบม่านตาเข้มขึ้นนิด (ตาลึก)
  const rg = c.createRadialGradient(cx, cy, r * 0.7, cx, cy, r + 4);
  rg.addColorStop(0, 'rgba(24,30,6,0)');
  rg.addColorStop(1, 'rgba(24,30,6,.38)');
  c.fillStyle = rg;
  c.fillRect(cx - r - 8, cy - r - 8, (r + 8) * 2, (r + 8) * 2);
  // รูม่านตาดำโต (เลื่อนตามสายตา) + วงเขียวเข้มฟุ้งรอบ
  const px = cx + lx * 0.8, py = cy - 4 + ly * 0.8, pr = r * 0.6;   // ผู้ใช้ 22 ต.ค.: ตาดำโตขึ้น
  const ring = c.createRadialGradient(px, py, pr, px, py, pr + 6);
  ring.addColorStop(0, col.ring);
  ring.addColorStop(1, 'rgba(42,50,8,0)');
  c.fillStyle = ring;
  c.beginPath(); c.arc(px, py, pr + 6, 0, TAU); c.fill();
  const pg = c.createRadialGradient(px - pr * 0.2, py - pr * 0.3, pr * 0.1, px, py, pr);
  pg.addColorStop(0, col.pupilIn);
  pg.addColorStop(1, col.pupilOut);
  c.fillStyle = pg;
  c.beginPath(); c.arc(px, py, pr, 0, TAU); c.fill();
  // แสงสะท้อนนุ่มครึ่งล่าง (ตาใส)
  const gl = c.createRadialGradient(cx, cy + r * 0.62, 0, cx, cy + r * 0.62, r * 0.72);
  gl.addColorStop(0, col.glow);
  gl.addColorStop(1, 'rgba(250,246,176,0)');
  c.fillStyle = gl;
  c.fillRect(cx - r - 8, cy - r - 8, (r + 8) * 2, (r + 8) * 2);
  // เงาเปลือกตาตกลงในม่านตา (เลื่อนตามเปลือกตา)
  const ld = lid * r * 0.7;
  const sh = c.createLinearGradient(0, cy - r * 0.9 + ld, 0, cy - r * 0.2 + ld);
  sh.addColorStop(0, 'rgba(14,18,4,.55)');
  sh.addColorStop(1, 'rgba(14,18,4,0)');
  c.fillStyle = sh;
  c.fillRect(cx - r - 8, cy - r - 8, (r + 8) * 2, r + 8 + ld);
  // ประกาย (ตัวเมีย): วงใหญ่บนขวาของรูม่านตา + จุดเล็กล่างซ้าย · ตาปรือ = ประกายต่ำลงนิดไม่จมใต้เปลือกตา
  const dot = eyeDots(c, px, py, pr, starDots, t, starOne);
  const dy = Math.min(1, lid) * 0.5;
  dot(0.34, -0.42 + dy, 0.36, true);
  if (starDots || !starOne) dot(-0.42, 0.5, 0.14);
  if (sparkle > 0 && !starDots) {
    const k = sparkle * (0.75 + 0.25 * Math.sin(t * 0.25));
    star4(c, px - pr * 0.5, py + pr * 0.55, 9 * k);
  }
  c.restore();
  void white;
}
/**
 * เปลือกตาลายวัว (ตามแบบ): ไลเนอร์ดำตามขอบบนของ dollEyeGeo — หัวตาบาง → หางตาหนา + ปลายเชิดแหลมเลยหางตา
 * + ขนตางอนสามเส้นที่มุมบนนอก (ยาว → สั้น) + ขอบตาล่างเส้นบางเรียวสองปลาย
 * ทุกเส้นรับ ink → บนปื้นดำ (ตาขวา) inkOver วาดซ้ำเป็นสีขาวทั้งชุด · sq/cy = ตาหรี่ · lid = เปลือกตาเลื่อนลง (ตาปรือ)
 */
function drawDollLashes(c, side, sq = 1, cyS = null, ink = '#1E1614', lid = 0) {
  const E = dollEyeGeo(side, lid), { po, o } = E;
  const yc = cyS ?? EYE_WHITE[side].y;
  const S = ([x, y]) => [x, yc + (y - yc) * sq];
  const nrm = (f, u, down) => {   // ทิศตั้งฉากเส้นที่ u (down = ชี้ลง ไม่งั้นชี้ขึ้น)
    const [x0, y0] = f(Math.max(0, u - 0.01)), [x1, y1] = f(Math.min(1, u + 0.01));
    const l = Math.hypot(x1 - x0, y1 - y0) || 1;
    let nx = -(y1 - y0) / l, ny = (x1 - x0) / l;
    if (down ? ny < 0 : ny > 0) { nx = -nx; ny = -ny; }
    return [nx, ny];
  };
  c.fillStyle = ink;
  // ไลเนอร์บน
  const n = 40, top = [], bot = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n, [x, y] = E.top(u), [nx, ny] = nrm(E.top, u, false);
    const th = (2.6 + 6.8 * Math.pow(u, 0.8)) * Math.min(1, u * 5 + 0.3);
    bot.push(S([x - nx * 1.6, y - ny * 1.6]));
    top.push(S([x + nx * th, y + ny * th]));
  }
  // ปลายเชิดเลยหางตา: ต่อเส้นไลเนอร์ออกไปตามทิศหางตาเนียน ๆ (ไม่หักมุม)
  const tan = (u) => {   // ทิศเดินตามเส้นเปลือกตา (หัวตา → หางตา)
    const [x0, y0] = E.top(Math.max(0, u - 0.01)), [x1, y1] = E.top(Math.min(1, u + 0.01));
    const l = Math.hypot(x1 - x0, y1 - y0) || 1;
    return [(x1 - x0) / l, (y1 - y0) / l];
  };
  const [tx, ty] = tan(1), [ex, ey] = nrm(E.top, 1, false);
  const raw = (i) => {   // จุดไลเนอร์ที่ยังไม่บีบตา (คำนวณปลายเชิดก่อน แล้วค่อยบีบ)
    const [x, y] = E.top(i / n), [nx, ny] = nrm(E.top, i / n, false);
    const th = (2.6 + 6.8 * Math.pow(i / n, 0.8)) * Math.min(1, (i / n) * 5 + 0.3);
    return { lo: [x - nx * 1.6, y - ny * 1.6], hi: [x + nx * th, y + ny * th] };
  };
  const end = raw(n);
  const wl = Math.hypot(1, 0.75), tip = [po[0] + o * 18 / wl + ex * 2, po[1] - 18 * 0.75 / wl + ey * 2];   // ปลายเชิดชี้ขึ้น-ออกนอกหน้า (ผู้ใช้ 22 ต.ค. "ตอนนี้มันคว่ำล่าง")
  const band = new Path2D();
  band.moveTo(...bot[0]);
  for (const p of bot.slice(1)) band.lineTo(...p);
  band.quadraticCurveTo(...S([end.lo[0] + o * 8, end.lo[1] - 3]), ...S(tip));
  const i0 = Math.round(n * 0.9), back = raw(i0).hi;   // ขอบบนของปลายเชิดกลับมาเกาะไลเนอร์ก่อนถึงหางตา → ปีกทึบชิ้นเดียว ไม่มีรอยบาก
  band.quadraticCurveTo(...S([(tip[0] + back[0]) / 2, (tip[1] + back[1]) / 2 + 1]), ...top[i0]);
  for (let i = i0 - 1; i >= 0; i--) band.lineTo(...top[i]);
  band.closePath();
  c.fill(band);
  // ขนตางอนสามเส้นที่มุมบนนอก (ผู้ใช้ 22 ต.ค. "เส้นหงิกงอ" → วาดใหม่): ทรงจันทร์เสี้ยวโค้งเดียวเนียน ๆ
  // ฐานกว้างฝังในไลเนอร์ → ออกตั้งฉาก แล้วค่อย ๆ โค้งไปทางหางตา ปลายแหลม (ไม่หักเป็นตะขอ) · เส้นนอกยาวกว่า งอนมากกว่า
  for (const [u, len, w, curl] of []) {   // ผู้ใช้ 22 ต.ค.: "เหลือเส้นเดียว ชี้ขึ้น" แล้ว "เอาเส้นบางออกเลย" → ไม่มีขนตาแยก เหลือไลเนอร์ + ปลายเชิด (เก็บโค้ดไว้เผื่อใส่กลับ)
    const [x, y] = E.top(u), [nx, ny] = nrm(E.top, u, false), [qx, qy] = tan(u);
    const th = 2.6 + 6.8 * Math.pow(u, 0.8);
    const bx = x + nx * (th - 3), by = y + ny * (th - 3);
    const k = [bx + nx * len * 0.62, by + ny * len * 0.62];
    const tp = [bx + nx * len * 0.9 + o * len * 0.42 * curl, by + ny * len * 0.9 - len * 0.1 * curl];   // งอนออกนอกหน้าแนวราบ-ขึ้น ไม่ตามเส้นเปลือกตาที่ลาดลงตรงหางตา
    const p = new Path2D();
    p.moveTo(...S([bx - qx * w, by - qy * w]));
    p.quadraticCurveTo(...S([k[0] - qx * w * 0.7, k[1] - qy * w * 0.7]), ...S(tp));
    p.quadraticCurveTo(...S([k[0] + qx * w * 0.35, k[1] + qy * w * 0.35]), ...S([bx + qx * w, by + qy * w]));
    p.closePath();
    c.fill(p);
  }
  // ขอบตาล่าง: เส้นบาง หนาสุดค่อนไปทางหางตา เรียวแหลมสองปลาย (บางกว่าไลเนอร์บนมาก)
  const m = 30, li = [], lo = [];
  for (let i = 0; i <= m; i++) {
    const u = i / m, [x, y] = E.bot(u), [nx, ny] = nrm(E.bot, u, true);
    const th = 0.3 + 2.2 * Math.pow(Math.sin(Math.PI * Math.min(1, u * 1.15)), 0.8);
    li.push(S([x - nx * 0.6, y - ny * 0.6]));
    lo.push(S([x + nx * th, y + ny * th]));
  }
  const rim = new Path2D();
  rim.moveTo(...li[0]);
  for (const q of li.slice(1)) rim.lineTo(...q);
  for (let i = m; i >= 0; i--) rim.lineTo(...lo[i]);
  rim.closePath();
  c.fill(rim);
}
/**
 * ตาหลับแปลงจากตาลืมของแต่ละตัว (ผู้ใช้ 21 ต.ค. เริ่มที่วิลาศ แล้วสั่ง "ทำแบบนี้ทุกสี เปลือกตาใครเปลือกตามัน")
 * เส้นเปลือกตาปิด = โค้งจากหัวตา (a) ถึงหางตา (b) ผ่านจุดดึง k · หนาตามเปลือกตาบนของตาลืมแบบนั้น (th(u): u 0 = หัวตา → 1 = หางตา)
 * ปลายหางตา: wing = ปลายเชิดแหลมแบบตาแมว (วิลาศ · โกนจา) · ไม่มี = ปลายมน (ไลเนอร์/เปลือกตาของตากลม)
 * ขนตา (ตัวเมีย — ทรงตามขนตาตอนลืมของตัวนั้น): ยิ้มหยี ∩ งอกขึ้นจากขอบบน · หลับ ∪ ห้อยลงจากขอบล่างงอนออกนอกหน้า
 * lower = ขนตาล่างจิ๋ว (โกนจา · เฉพาะ ∩) · ไม่มีจุดประกาย (ปิดตาแล้วไม่มีแสงสะท้อน)
 * kind: 'blink' = หลับ/กะพริบ (โค้งลง ∪) · 'happy' = ยิ้มหยี/ขยิบ (โค้งขึ้น ∩) · 'yawn' = หาว (โค้งลงลึก หนาขึ้น)
 */
function drawClosedLid(c, kind, L) {
  const { a, b, k, o, th: thAt } = L;
  const up = kind === 'happy', above = 0.55;   // ส่วนของความหนาที่อยู่เหนือเส้นโค้ง
  const Q = (u) => {   // จุดบนเส้นเปลือกตา + ทิศตั้งฉากชี้ขึ้น + ทิศเดินหน้า
    const v = 1 - u;
    const x = v * v * a[0] + 2 * v * u * k[0] + u * u * b[0], y = v * v * a[1] + 2 * v * u * k[1] + u * u * b[1];
    const dx = 2 * v * (k[0] - a[0]) + 2 * u * (b[0] - k[0]), dy = 2 * v * (k[1] - a[1]) + 2 * u * (b[1] - k[1]);
    const l = Math.hypot(dx, dy) || 1;
    let nx = dy / l, ny = -dx / l;
    if (ny > 0) { nx = -nx; ny = -ny; }
    return { x, y, nx, ny, tx: dx / l, ty: dy / l };
  };
  const n = 36, top = [], bot = [];
  for (let i = 0; i <= n; i++) {
    const u = i / n, q = Q(u), th = thAt(u);
    top.push([q.x + q.nx * th * above, q.y + q.ny * th * above]);
    bot.push([q.x - q.nx * th * (1 - above), q.y - q.ny * th * (1 - above)]);
  }
  // ปลายมน: ครึ่งวงรอบปลายเส้น (t = ทิศออกจากปลาย)
  const cap = (p, from, to, t, r) => {
    p.quadraticCurveTo(from[0] + t[0] * r, from[1] + t[1] * r, (from[0] + to[0]) / 2 + t[0] * r, (from[1] + to[1]) / 2 + t[1] * r);
    p.quadraticCurveTo(to[0] + t[0] * r, to[1] + t[1] * r, ...to);
  };
  const e = Q(1), s0 = Q(0);
  const p = new Path2D();
  p.moveTo(...bot[0]);
  for (const q of bot.slice(1)) p.lineTo(...q);
  if (L.wing) {
    // ปลายเชิดเลยหางตา: ต่อทิศเส้นออกไปแล้วงอนขึ้น (ตัวเดียวกับปลายเปลือกตาตอนลืม)
    const { len, out, rise, lift } = L.wing;
    const tip = [b[0] + e.tx * len + o * out, b[1] + e.ty * len - rise];
    p.quadraticCurveTo(b[0] + e.tx * len * 0.54, b[1] + e.ty * len * 0.54 + 1, ...tip);
    p.quadraticCurveTo(b[0] + e.tx * len * 0.38 - o, b[1] + e.ty * len * 0.38 - lift, ...top[n]);
  } else cap(p, bot[n], top[n], [e.tx, e.ty], thAt(1) / 2);
  for (let i = n - 1; i >= 0; i--) p.lineTo(...top[i]);
  cap(p, top[0], bot[0], [-s0.tx, -s0.ty], thAt(0) / 2);
  p.closePath();
  c.save();
  c.lineJoin = 'round';
  // edge = ขอบสว่างรอบเส้นตาหลับ (ตาที่อยู่บนขนเข้ม — สีเปรอะ: เส้นดำกลืนกับขนจนมองไม่เห็นว่าหลับตา)
  //   บนขนสีอ่อนขอบสีอ่อนกลืนหายเอง ไม่ต้องแยกข้าง · ปื้นดำบนพื้นขาว (ลายวัว) ใช้เส้นขาวแทน (inkOver ใน drawCat2)
  if (L.edge) {
    c.strokeStyle = L.edge;
    c.lineWidth = 5;
    c.stroke(p);
  }
  c.fillStyle = L.ink;
  c.strokeStyle = L.ink;
  c.lineWidth = 1.6;   // ขอบมน ไม่แตกเป็นหยัก
  c.fill(p);
  c.stroke(p);
  // ขนตา: [u บนเส้น, ยาว, ครึ่งกว้างฐาน, แรงงอนออกนอกหน้า]
  for (const [u, len, w, curl = 1] of L.lashes || []) {
    const q = Q(u), th = thAt(u);
    const sg = up ? 1 : -1;   // ทิศงอก (ตั้งฉากชี้ขึ้น / ลง)
    const nx = q.nx * sg, ny = q.ny * sg;
    const h = th * (up ? above : 1 - above) - 1.5;
    const b0 = [q.x + nx * h, q.y + ny * h];
    const kk = [b0[0] + nx * len * 0.7, b0[1] + ny * len * 0.7];
    const tp = [kk[0] + o * len * 0.55 * curl, kk[1] + (up ? -len * 0.1 : len * 0.05)];
    const sd = [-ny, nx];
    const P = new Path2D();
    P.moveTo(b0[0] + sd[0] * w, b0[1] + sd[1] * w);
    P.quadraticCurveTo(kk[0] + sd[0] * w * 0.5, kk[1] + sd[1] * w * 0.5, ...tp);
    P.quadraticCurveTo(kk[0] - sd[0] * w * 0.3, kk[1] - sd[1] * w * 0.3, b0[0] - sd[0] * w, b0[1] - sd[1] * w);
    P.closePath();
    c.fill(P);
  }
  // ขนตาล่างจิ๋ว (∩ เท่านั้น): จากขอบล่างชี้ลง-ออกนอก
  if (up) for (const [u, len, w] of L.lower || []) {
    const q = Q(u), h = thAt(u) * (1 - above) - 1;
    const b0 = [q.x - q.nx * h, q.y - q.ny * h];
    const tip = [b0[0] - q.nx * len + o * len * 0.35, b0[1] - q.ny * len];
    const P = new Path2D();
    P.moveTo(b0[0] - q.ny * w, b0[1] + q.nx * w);
    P.quadraticCurveTo(b0[0] - q.nx * len * 0.6, b0[1] - q.ny * len * 0.6, ...tip);
    P.lineTo(b0[0] + q.ny * w, b0[1] - q.nx * w);
    P.closePath();
    c.fill(P);
  }
  c.restore();
}
/**
 * เปลือกตาปิดของแต่ละแบบตา (คู่กับ drawClosedLid) — ดึงจากตาลืมของตัวนั้น:
 *   วิลาศ: มุมตาอัลมอนด์ (wilatEyeGeo) · หนาไปหางตา + ปลายเชิด + ขนตาสองเส้น
 *   ตาแบ๊ว (น้องส้ม ไข่มุก): ไลเนอร์โอบหางตา หนาสุดที่หางตา ปลายมน · ตัวเมียขนตาสามเส้นแบบแฉกขนตาตอนลืม
 *   ขนตาพัด (โกนจา): เส้นบางกว่า + หางไลเนอร์ตวัดยาวแบบตาแมว + ขนตาม้วนสามเส้น + ขนตาล่างจิ๋ว
 *   ตากลม (ขนมชั้น): เปลือกตาเรียว → หนาที่หางตา ปลายมน + ขนตางอนยาวสามเส้น
 *   ศุภลักษณ์: เส้นเปลือกตาเอียง (หางตาสูง) หนาไปหางตา + ปลายตวัดสั้น
 *   โคราช: เส้นเปลือกตาบาง หนาขึ้นค่อนหางตา ปลายมน (ตัวผู้ ไม่มีขนตา)
 *   ลายสลิด: ไลเนอร์หนาไปหางตา หางตวัดสั้น + ขนตาพัดสี่เส้น
 *   หน้ากวน (วิเชียรมาศ): เส้นเปลือกตาหนาเท่ากันตลอด ปลายมนสองข้าง หางตาสูงหัวตาต่ำแบบตาลืม · สีเส้นตัว
 */
function closedLidSpec(side, kind, s, female, pal) {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const up = kind === 'happy', deep = kind === 'yawn', D = deep ? 1.15 : 1;
  const ramp = (u) => Math.min(1, u * 5 + 0.3);   // หัวตาเรียวเล็ก
  const lashes = (list) => (female ? list : []);
  if (s?.eyeStyle === 'wilat') {
    const { pi, po, cx, cy, r } = wilatEyeGeo(side);
    return {
      o, ink: pal.closedInk || '#0E0A08',
      // ยิ้มหยี: มุมตาต่ำลงนิด (แก้มดันขึ้น) แล้วโค้งขึ้น · หลับ: มุมตาที่เดิม เปลือกตาโค้งลงมาปิด
      a: up ? [pi[0], pi[1] + r * 0.3] : pi, b: up ? [po[0], po[1] + r * 0.36] : po,
      k: up ? [cx + o * r * 0.05, cy - r * 0.62] : [cx + o * r * 0.12, cy + r * (deep ? 0.95 : 0.58)],
      th: (u) => (1.6 + 7.4 * Math.pow(u, 0.85)) * ramp(u) * D,
      wing: { len: 13, out: 3, rise: up ? 9 : 7, lift: 6 },
      lashes: lashes([[0.8, 11, 2.6], [0.6, 9, 2.2]]),
    };
  }
  if (s?.eyeStyle === 'supha') {
    // ศุภลักษณ์: หัวตาระดับกลางตา หางตาสูง (เส้นเปลือกตาเอียงแบบตาลืม) · หนาไปหางตา + ปลายตวัดสั้น · ตัวผู้ไม่มีขนตา
    const { pi, po, cx, cy, r } = suphaEyeGeo(side);
    return {
      o, ink: pal.closedInk || '#22100A',
      a: up ? [pi[0], pi[1] + r * 0.3] : deep ? [pi[0], pi[1] - r * 0.1] : pi,
      b: up ? [po[0], po[1] + r * 0.42] : deep ? [po[0], po[1] - r * 0.05] : [po[0], po[1] + r * 0.12],
      k: up ? [cx, cy - r * 0.5] : [cx + o * r * 0.1, cy + r * (deep ? 0.95 : 0.6)],
      th: (u) => (2 + 7.5 * Math.pow(u, 0.9)) * ramp(u) * D,
      wing: { len: 10, out: 2, rise: up ? 6 : 5, lift: 5 },
      lashes: lashes([[0.8, 11, 2.6], [0.6, 9, 2.2]]),
    };
  }
  if (s?.art?.grumpy) {
    // หน้ากวน: หางตาสูง หัวตา (ข้างจมูก) ต่ำ เหมือนเส้นเปลือกตาตอนลืม — ปิดลงมาทั้งเส้น
    const lw = 8 * LINE_K * D;
    return {
      o, ink: pal.line,
      a: [W.x - o * (R + 2), W.y + (up ? 16 : deep ? 2 : 10)], b: [W.x + o * (R + 2), W.y + (up ? 8 : deep ? -8 : -2)],
      k: up ? [W.x, W.y - 22] : [W.x + o * 4, W.y + (deep ? 44 : 26)],   // ∩ โก่งพอ ไม่แบนจนดูเป็นคิ้ว
      th: () => lw,
    };
  }
  // ตาวงกลม (ตาแบ๊ว · ตากลม · ขนตาพัด): มุมตาสองข้างที่แนวกลางตา
  const base = {
    o,
    a: up ? [W.x - o * R * 0.86, W.y + 16] : deep ? [W.x - o * R * 0.8, W.y - 2] : [W.x - o * R * 0.9, W.y + 4],
    b: up ? [W.x + o * R * 0.94, W.y + 13] : deep ? [W.x + o * R * 0.9, W.y - 6] : [W.x + o * R * 0.98, W.y],
    k: up ? [W.x, W.y - 28] : [W.x + o * 3, W.y + (deep ? 56 : 40)],
  };
  if (s?.eyeStyle === 'korat') return {
    // โคราช: เปลือกตาเส้นเข้มบาง หนาขึ้นค่อนหางตา ปลายมน · ตัวผู้ไม่มีขนตา
    ...base, ink: pal.closedInk || '#2A1E1C',
    th: (u) => (2.2 + 6.4 * Math.pow(u, 0.9)) * ramp(u) * D,
  };
  if (s?.eyeStyle === 'hazel') return {
    // สีเปรอะ: เปลือกตาหนาไปทางหางตาแบบตาลืม ปลายมน · ตัวผู้ไม่มีขนตา · ขอบส้มอ่อนรอบเส้น (ขนเข้มรอบตา)
    ...base, ink: pal.closedInk || '#1E120C', edge: 'rgba(240,190,130,.55)',
    th: (u) => (2.2 + 7.4 * Math.pow(u, 1.25)) * ramp(u) * D,
  };
  if (s?.eyeStyle === 'doll') {
    // ลายวัว (รอบสอง 22 ต.ค.): มุมตาจาก dollEyeGeo · ไลเนอร์หนาไปหางตา + ปลายเชิด + ขนตาสามเส้นแบบตอนลืม
    // ตาขวาอยู่บนปื้นดำ: ส่วนที่ทับปื้นวาดซ้ำเป็นเส้นขาว (inkOver ใน drawCat2)
    const { pi, po, cx, cy, r } = dollEyeGeo(side);
    return {
      o, ink: pal.closedInk || '#1E1614',
      a: up ? [pi[0], pi[1] + r * 0.28] : pi, b: up ? [po[0], po[1] + r * 0.4] : po,
      k: up ? [cx + o * r * 0.05, cy - r * 0.62] : [cx + o * r * 0.1, cy + r * (deep ? 0.98 : 0.62)],
      th: (u) => (1.8 + 6.6 * Math.pow(u, 0.95)) * ramp(u) * D,
      wing: { len: 12, out: 3, rise: up ? 9 : 7, lift: 6 },
      lashes: [],   // ไม่มีขนตาแยกแบบตอนลืม (ผู้ใช้ 22 ต.ค.)
    };
  }
  if (s?.lashStyle === 'salid') return {
    // ลายสลิด: ไลเนอร์หนาไปหางตา + หางตวัดสั้น + ขนตาพัดสี่เส้น
    ...base, ink: pal.closedInk || '#24150D',
    th: (u) => (2 + 6.4 * Math.pow(u, 1.05)) * ramp(u) * D,
    wing: { len: 12, out: 3, rise: up ? 8 : 6, lift: 6 },
    lashes: lashes([[0.92, 13, 2.8, 1], [0.8, 13, 2.7, 0.85], [0.68, 11, 2.5, 0.7], [0.56, 9, 2.3, 0.55]]),
  };
  if (s?.lashStyle === 'fan') return {
    ...base, ink: pal.closedInk || '#080303',
    th: (u) => (1.4 + 6 * Math.pow(u, 1.3)) * ramp(u) * D,
    wing: { len: 18, out: 4, rise: up ? 15 : 12, lift: 10 },
    lashes: lashes([[0.88, 15, 3.2, 1], [0.74, 15, 3, 0.8], [0.6, 11, 2.8, 0.6]]),
    lower: female ? [[0.9, 7, 2], [0.97, 6, 1.8]] : [],
  };
  if (s?.eyeStyle === 'round') return {
    ...base, ink: pal.closedInk || '#24140C',
    th: (u) => (2.4 + 7.6 * Math.pow(u, 1.1)) * ramp(u) * D,
    lashes: lashes([[0.9, 17, 3.6, 1], [0.75, 15, 3.4, 0.75], [0.6, 12, 3, 0.5]]),
  };
  return {
    ...base, ink: pal.closedInk || '#2A170E',
    th: (u) => (2.2 + 8.6 * Math.pow(u, 1.1)) * ramp(u) * D,   // ตาโต — เส้นหนากว่าแบบอื่นนิด ไม่งั้นดูจางเทียบกับขนาดตา
    lashes: lashes([[0.9, 12, 3, 0.9], [0.76, 14, 3.2, 0.7], [0.62, 9, 2.6, 0.5]]),
  };
}
/**
 * ลายขาวอกแมววิลาศ (ตามแบบ): ผ้ากันเปื้อนขนฟูกว้างใต้คาง ขอบเป็นปอยขน → เรียวลงเป็นเส้นบางกลางท้องถึงหว่างขา
 * cx/y0/y1 = กลาง/บน/ล่าง (พิกัดชิ้น) · k = สเกลความกว้าง · M = ตัวแปลงจุด (ตัววิ่ง)
 */
function wilatChestPath(cx, y0, y1, k = 1, M = null) {
  const prof = [[0, 34], [0.05, 42], [0.11, 46], [0.17, 40], [0.24, 28], [0.32, 16], [0.42, 10], [0.6, 8], [0.8, 6], [0.94, 3.5], [1, 1]];
  const wAt = (u) => {
    for (let i = 1; i < prof.length; i++) if (u <= prof[i][0]) { const [u0, w0] = prof[i - 1], [u1, w1] = prof[i]; return w0 + ((w1 - w0) * (u - u0)) / (u1 - u0); }
    return 1;
  };
  const R = [], L = [];
  const n = 26;
  for (let i = 0; i <= n; i++) {
    const u = i / n, y = y0 + (y1 - y0) * u;
    const fur = u > 0.03 && u < 0.34 ? (i % 2 ? 6 : -3) * (1 - u * 1.6) : 0;    // ปอยขนตามขอบผ้ากันเปื้อน (เล็กลงทางล่าง)
    const fur2 = u > 0.03 && u < 0.34 ? (i % 2 ? -2.5 : 5.5) * (1 - u * 1.6) : 0;
    R.push([cx + (wAt(u) + fur) * k, y]);
    L.push([cx - (wAt(u) + fur2) * k, y]);
  }
  const pts = [...R, ...L.reverse()];
  return smoothLoop(M ? pts.map((p) => M(p)) : pts);
}

/**
 * ขนตาแมวลายสลิด (ผู้ใช้ 21 ต.ค.: "ขนตาแอบแปลก วาดใหม่" — ตามแบบ): อายไลเนอร์ดำหนาตามขอบตาบน (หัวตาบาง → หางตาหนา)
 * ตวัดหางสั้นเชิดออกนอกหน้าที่หางตา + ขนตางอนสี่เส้นเรียงเป็นพัดที่มุมบนนอก (เส้นนอกยาวงอนสุด) · ไม่มีแถบโอบใต้ตา
 * sq/cy = ตาหรี่ (ฐานเกาะขอบตาที่หรี่) เหมือน drawRoundLashes
 */
function drawSalidLashes(c, side, sq = 1, cy = null, ink = '#24150D') {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const yc = cy ?? W.y;
  const P = (a, r) => [W.x + o * Math.cos(a) * r, yc + (W.y + Math.sin(a) * r - yc) * sq];
  const N = (a) => { const nx = o * Math.cos(a) * sq, ny = Math.sin(a), l = Math.hypot(nx, ny) || 1; return [nx / l, ny / l]; };
  c.fillStyle = ink;
  // อายไลเนอร์: หัวตาบน (a −2.7) → หางตา (a −0.08) หนา 1.5 → 7
  const a0 = -2.7, a1 = -0.08, n = 40, lid = new Path2D(), out = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n), u = i / n;
    const th = (1.5 + 5.5 * Math.pow(u, 1.1)) * Math.min(1, u * 5 + 0.3);
    const b = P(a, R - 1.5), nn = N(a);
    if (!i) lid.moveTo(...b); else lid.lineTo(...b);
    out.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  // หางตวัดเชิดขึ้น-ออกนอกหน้า (ผู้ใช้ 22 ต.ค. "ปรับขนตาให้ดูดีขึ้น"): ปีกทึบชิ้นเดียวเรียวแหลม
  // ขอบล่างต่อจากขอบตาไปปลาย · ขอบบนกลับมาเกาะไลเนอร์ก่อนถึงหางตา (ไม่เป็นก้อนกลม ไม่มีรอยบาก)
  const tipW = [W.x + o * (R + 18), yc + (W.y - 9 - yc) * sq];
  const i0 = n - 3;
  lid.quadraticCurveTo(W.x + o * (R + 8), yc + (W.y - 1 - yc) * sq, ...tipW);
  lid.quadraticCurveTo((tipW[0] + out[i0][0]) / 2, (tipW[1] + out[i0][1]) / 2 + 1, ...out[i0]);
  for (let i = i0 - 1; i >= 0; i--) lid.lineTo(...out[i]);
  lid.closePath();
  c.fill(lid);
  // ขนตางอนสี่เส้นเรียงเป็นพัดที่มุมบนนอก — ทรงจันทร์เสี้ยวโค้งเดียวเนียน (เดิมขึ้นตรงแล้วหักข้างเป็นตะขอ ดูเป็นหนาม)
  // ฐานกว้างฝังในไลเนอร์ → ออกตั้งฉากขอบตา → ค่อย ๆ โค้งออกนอกหน้า ปลายแหลม · เส้นนอกยาวสุด เรียงสั้นลงเข้าหากลางตา
  for (const [a, len, w, curl] of [[-0.42, 17, 3.3, 1], [-0.72, 16, 3.1, 0.85], [-1.02, 14, 2.8, 0.7], [-1.32, 11, 2.4, 0.55]]) {
    const u = (a - a0) / (a1 - a0), th = (1.5 + 5.5 * Math.pow(u, 1.1)) * Math.min(1, u * 5 + 0.3);
    const nn = N(a), b0 = P(a, R - 1.5), sd = [-nn[1], nn[0]];
    const bb = [b0[0] + nn[0] * (th - 2.5), b0[1] + nn[1] * (th - 2.5)];
    const k = [bb[0] + nn[0] * len * 0.6, bb[1] + nn[1] * len * 0.6];
    const tip = [bb[0] + nn[0] * len * 0.88 + o * len * 0.45 * curl, bb[1] + nn[1] * len * 0.88 - len * 0.08 * curl];
    const q = new Path2D();
    q.moveTo(bb[0] + sd[0] * w, bb[1] + sd[1] * w);
    q.quadraticCurveTo(k[0] + sd[0] * w * 0.6, k[1] + sd[1] * w * 0.6, ...tip);
    q.quadraticCurveTo(k[0] - sd[0] * w * 0.3, k[1] - sd[1] * w * 0.3, bb[0] - sd[0] * w, bb[1] - sd[1] * w);
    q.closePath();
    c.fill(q);
  }
}
/**
 * ขนตาแบบตาแมว (โกนจา · ผู้ใช้ขอ "ดีไซน์ขนตาใหม่ไม่ซ้ำกับตัวอื่น"):
 *   อายไลเนอร์โอบขอบตาบนแล้ว "ตวัดหาง" เลยหางตาออกไปเป็นปลายแหลมเชิดขึ้น (cat-eye — ตัวอื่นไม่มีหางไลเนอร์)
 *   + ขนตางอนสามเส้นโค้งม้วนออกนอกหน้า (โค้งนุ่ม ไม่ใช่หนามตรง) + ขนตาล่างจิ๋วสองเส้นที่มุมล่างนอก
 * สีดำสนิท (ขนดำ → น้ำตาลเข้มจมหาย) · sq/cy = ตาหรี่ เหมือน drawLashes
 */
function drawFanLashes(c, side, sq = 1, cy = null, ink = '#080303') {
  const W = EYE_WHITE[side], R = EYE_WHITE.r, o = side === 'left' ? -1 : 1;   // o = ทิศออกนอกหน้า
  const yc = cy ?? W.y;
  const P = (a, r) => [W.x + o * Math.cos(a) * r, yc + (W.y + Math.sin(a) * r - yc) * sq];
  const N = (a) => { const nx = o * Math.cos(a) * sq, ny = Math.sin(a), l = Math.hypot(nx, ny) || 1; return [nx / l, ny / l]; };
  c.fillStyle = ink;
  // อายไลเนอร์: หัวตาบน (a −2.5) → หางตา (a 0.05) หนาขึ้นทางหางตา (1 → 5)
  const a0 = -2.5, a1 = 0.05, n = 36, lid = new Path2D(), out = [];
  for (let i = 0; i <= n; i++) {
    const a = a0 + (a1 - a0) * (i / n), u = i / n;
    const th = (1 + 4 * Math.pow(u, 1.4)) * Math.min(1, u * 6);
    const b = P(a, R - 1.5), nn = N(a);
    if (!i) lid.moveTo(...b); else lid.lineTo(...b);
    out.push([b[0] + nn[0] * th, b[1] + nn[1] * th]);
  }
  for (let i = n; i >= 0; i--) lid.lineTo(...out[i]);
  lid.closePath();
  c.fill(lid);
  // หางไลเนอร์ (ทรงตาแมว): ฐานกว้างคร่อมมุมตาบนนอก (a −0.42 ถึง 0.1) → ปลายแหลมเชิดขึ้นออกนอกหน้า
  const wTop = P(-0.42, R + 3), wBot = P(0.1, R - 1);
  const wTip = [W.x + o * (R + 22), yc + (W.y - 20 - yc) * sq];
  const wing = new Path2D();
  wing.moveTo(...wTop);
  wing.quadraticCurveTo(W.x + o * (R + 10), yc + (W.y - 20 - yc) * sq, ...wTip);
  wing.quadraticCurveTo(W.x + o * (R + 9), yc + (W.y - 4 - yc) * sq, ...wBot);
  wing.closePath();
  c.fill(wing);
  // ขนตาหนึ่งเส้น: ฐานฝังในไลเนอร์ → ขึ้นตามแนวตั้งฉากขอบตา → ม้วนโค้งออกนอกหน้า (ปลายเรียวแหลม)
  const lash = (a, len, w, curl) => {
    const b = P(a, R + 2), nn = N(a), sd = [-nn[1], nn[0]];
    const k = [b[0] + nn[0] * len * 0.85, b[1] + nn[1] * len * 0.85];                                  // จุดโค้ง: ตั้งฉากขอบตา
    const tip = [b[0] + nn[0] * len * 0.6 + o * len * 0.7 * curl, b[1] + nn[1] * len * 0.6 - len * 0.18 * curl];   // ปลาย: ม้วนออกนอก
    const q = new Path2D();
    q.moveTo(b[0] + sd[0] * w - nn[0] * 3, b[1] + sd[1] * w - nn[1] * 3);
    q.quadraticCurveTo(k[0] + sd[0] * w * 0.5, k[1] + sd[1] * w * 0.5, ...tip);
    q.quadraticCurveTo(k[0] - sd[0] * w * 0.2, k[1] - sd[1] * w * 0.2, b[0] - sd[0] * w - nn[0] * 3, b[1] - sd[1] * w - nn[1] * 3);
    q.closePath();
    c.fill(q);
  };
  // บน: [มุมบนขอบตา, ยาว, ครึ่งกว้างฐาน, แรงม้วน] — กลุ่มที่มุมบนนอก เส้นนอกม้วนมากสุด
  for (const [a, len, w, curl] of [[-0.4, 16, 3.6, 1], [-0.78, 16, 3.4, 0.8], [-1.16, 12, 3, 0.6]]) lash(a, len, w, curl);
  // ล่าง: จิ๋ว ชี้ลง-ออกนอก
  for (const [a, len, w] of [[0.62, 8, 2.2], [0.98, 7, 2]]) {
    const b = P(a, R + 1), nn = N(a);
    const tip = [b[0] + nn[0] * len + o * len * 0.35, b[1] + nn[1] * len];
    const q = new Path2D();
    q.moveTo(b[0] - nn[1] * w, b[1] + nn[0] * w);
    q.quadraticCurveTo(b[0] + nn[0] * len * 0.6, b[1] + nn[1] * len * 0.6, ...tip);
    q.lineTo(b[0] + nn[1] * w, b[1] - nn[0] * w);
    q.closePath();
    c.fill(q);
  }
}

/**
 * แมวตัวอื่นของน้องแบบใหม่ — ทรงตัว/โครงเดียวกับน้องส้มทุกตัว (ใส่ชุดได้เหมือนกันหมด) ต่างกันแค่ จานสี · สีตา · ขนตา (เพศ)
 * pal  = จานสีเต็มชุดของแบบใหม่ (แทนการเดาจากช่องสีของสกินเดิม) · air = สีพ่นเงาขอบ (แมวส้มใช้ส้ม)
 * eyes = สีตาแยกข้างซ้าย/ขวาของจอ (ตาสองสีได้) · sex 'f' = ขนตาเพศเมีย (แมวส้มตัวหลักเป็นตัวผู้)
 * ช่องสีเดิม (cat line dark …) ใส่ไว้ด้วย — ตัววาดเดิม (เทียบแบบเดิม/หน้าอื่น) ยังวาดได้
 */
